-- Kingdom Heights' Royals News of October 30, 2026 (sent from Smore; written into the app from its text,
-- shaped by src/news/compose.ts). Kingdom Heights only.
insert into public.newsletters (id, title, sent_on, source_url, blocks) values
  ('4b1d6a0e-2c8f-4e3a-9a51-30a1c0de2026', 'Royals News', '2026-10-30', 'app:4b1d6a0e-2c8f-4e3a-9a51-30a1c0de2026', $news$[{"kind":"text","title":null,"paragraphs":[[{"text":"What an incredible week at Kingdom Heights! Our Royals brought the fun, excitement, and school spirit all week long as they celebrated Spirit Week. From creative dress-up days to our annual Fall Fest, students made lasting memories while enjoying time together as a school family."}],[{"text":"A special thank you goes to the many parents who generously volunteered their time, talents, and resources to help make Fall Fest such a success. Your willingness to serve is a beautiful reflection of the strength of our Kingdom Heights community, and we are truly grateful for your partnership."}],[{"text":"We also want to celebrate the success of our Dunk Tank for DC fundraiser! Thanks to the generosity of our students, families, and staff, we raised $787 to help send our 8th graders on their educational trip to Washington, D.C.!"}],[{"text":"Weeks like this remind us how thankful we are for our Kingdom Heights family. Thank you for making our school community such a special place where students can learn, grow, and create memories that will last a lifetime."}]]},{"kind":"heading","text":"Important Information"},{"kind":"text","title":"Book Fair 📚","paragraphs":[[{"text":"The Book Fair will be on campus for one final day on Monday, November 2. If you would like your student to purchase any remaining books, please send them with money that day, or feel free to visit the school and shop the Book Fair together."}]]},{"kind":"text","title":"6th-9th Grade E-Learning Day 📝","paragraphs":[[{"text":"Students in 6th-9th grade will have an E-Learning Day Tuesday, November 3rd - Wednesday, November 4th. Regular on-campus classes will resume on Thursday, November 5th."}]]},{"kind":"text","title":"Save the Date: K-12 Parent Meeting 👪","paragraphs":[[{"text":"Parents are asked to attend one of our upcoming parent meetings on Thursday, November 5. Two sessions will be offered to accommodate family schedules: Session 1: 1:45 PM | Session 2: 6:00 PM. Please plan to attend the session that works best for your family."}]]},{"kind":"text","title":"Save the Date: Preview Night 👑","paragraphs":[[{"text":"If you know a family in the community who may be interested in Kingdom Heights Preparatory School, our Preview Night on Monday, November 9, at 6:30 PM in the Rock Kids Sanctuary. This is a great opportunity to meet our faculty and staff, tour the campus, and experience what makes Kingdom Heights special."}]]},{"kind":"text","title":"PE Uniform Order Open ✅","paragraphs":[[{"text":"The PE Uniform Store is open until THIS Sunday, November 1. This will be the final order window for 2026. To order, visit "},{"text":"www.khroyals.com","href":"https://www.khroyals.com"},{"text":" and navigate to Student Life > PE Uniform Store."}]]},{"kind":"text","title":"Pizza Friday Fundraiser 🍕","paragraphs":[[{"text":"Pizza Friday is Friday, November 6, with all proceeds benefiting our 8th Grade Washington, D.C. Trip this spring. If you would like your K3-12th grade student to have pizza for lunch, please send payment in a labeled envelope or zip-lock bag with your child's name on it. Pizza is $3 per slice. All money must be turned in by Thursday, November 5."}]]},{"kind":"text","title":null,"paragraphs":[[{"text":"Thank you for supporting our eighth graders as they raise funds for this unforgettable educational experience!"}]]}]$news$::jsonb)
on conflict (id) do nothing;
